syntax:
def parse_port(text):
    try:
        value = int(text)
    except ValueError:
        return None

    if value <= 0:
        raise ValueError('port must be positive')
    return value

example:
def safe_ratio(a, b):
    if b == 0:
        return None
    return a / b


def test_safe_ratio():
    assert safe_ratio(10, 2) == 5
    assert safe_ratio(10, 0) is None
